-- Listage de la structure de vue building. billing_cycle_details_view
DROP VIEW IF EXISTS `billing_cycle_details_view`;
-- Suppression de la table temporaire et création finale de la structure d'une vue
DROP TABLE IF EXISTS `billing_cycle_details_view`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `billing_cycle_details_view` AS
select row_number() OVER () AS `id`,
       `bc`.`id`            AS `billing_cycle_id`,
       `bc`.`period_start`  AS `start_date`,
       `bc`.`period_end`    AS `end_date`,
       `bc`.`amount_due`    AS `amount_due`,
       `bc`.`status`        AS `billing_cycle_status`,
       `s`.`id`             AS `subscription_id`,
       `s`.`tenant_id`      AS `subscription_tenant_id`,
       `s`.`start_date`     AS `subscription_start_date`,
       `s`.`end_date`       AS `subscription_end_date`,
       `sv`.`id`            AS `service_id`,
       `sv`.`billing_mode`  AS `service_billing_mode`,
       `sv`.`code`          AS `service_code`,
       `sv`.`name`          AS `service_name`,
       `sv`.`description`   AS `service_description`,
       `t`.`id`             AS `tenant_id`,
       `u`.`id`             AS `user_id`,
       `u`.`first_name`     AS `user_first_name`,
       `u`.`last_name`      AS `user_last_name`,
       `u`.`username`       AS `user_username`,
       `p`.`id`             AS `payment_id`,
       `p`.`total_amount`   AS `payment_total_amount`,
       `p`.`payment_date`   AS `payment_date`,
       `pl`.`amount_paid`   AS `payment_line_amount_paid`
from ((((((`billing_cycles` `bc` left join `subscriptions` `s`
           on ((`bc`.`subscription_id` = `s`.`id`))) left join `services` `sv`
          on ((`s`.`service_id` = `sv`.`id`))) left join `tenants` `t`
         on ((`s`.`tenant_id` = `t`.`id`))) left join `users` `u`
        on ((`t`.`user_id` = `u`.`id`))) left join `payment_lines` `pl`
       on ((`bc`.`id` = `pl`.`billing_cycle_id`))) left join `payments` `p` on ((`pl`.`payment_id` = `p`.`id`)));

