-- Listage de la structure de vue building. subscription_payment_summary
DROP VIEW IF EXISTS `subscription_payment_summary`;
-- Suppression de la table temporaire et création finale de la structure d'une vue
DROP TABLE IF EXISTS `subscription_payment_summary`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `subscription_payment_summary` AS
select `s`.`id`                                                   AS `subscription_id`,
       `ss`.`id`                                                  AS `subscription_service_id`,
       `so`.`id`                                                  AS `subscription_option_id`,
       `s`.`total_price`                                          AS `subscription_total_price`,
       `ss`.`price`                                               AS `service_price`,
       `so`.`price`                                               AS `option_price`,
       coalesce(sum(`pl`.`amount_paid`), 0)                       AS `total_paid`,
       (`s`.`total_price` - coalesce(sum(`pl`.`amount_paid`), 0)) AS `remaining_balance`
from (((`subscriptions` `s` left join `subscription_services` `ss`
        on ((`ss`.`subscription_id` = `s`.`id`))) left join `subscription_options` `so`
       on ((`so`.`subscription_service_id` = `ss`.`id`))) left join `payment_lines` `pl`
      on ((`pl`.`billing_cycle_id` = `ss`.`billing_cycle_id`)))
group by `s`.`id`, `ss`.`id`, `so`.`id`;

